interface ActionAgentInteractionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    popupEntryId?: string
    runtime: ActionPopupRuntime
}

/** Agent interaction surface, including agent children started by command actions. */
export function ActionAgentInteraction(props: ActionAgentInteractionProps) {
    const { action, assignmentContext, popupEntryId, runtime } = props
    const {
        bindingStore, conversationStore, historyStore, inputStore, resultStore, runValidationError, scheduleStore,
        settingsStore, usageValuesService,
    } = runtime
    const boundRunId = useBoundRunId(bindingStore)
    const activeActionType = useRunSelector(boundRunId, (run) => run?.activeActionType ?? null)
    const question = useRunSelector(boundRunId, (run) => run?.question ?? null)
    const visible = action.type === 'agent' || activeActionType === 'agent'
    const displayedUsageValuesService = action.type === 'agent'
        && assignmentContext.kind === 'card'
        && !!assignmentContext.file
        && !!assignmentContext.cardInternalId
        ? usageValuesService
        : undefined

    if (!visible) return null

    return (
        <Stack sx={{ display: 'contents' }}>
            <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
                <ActionLogErrorOwner bindingStore={bindingStore} resultStore={resultStore} />
                <ActionConversationChat
                    actionId={action.id}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    popupEntryId={popupEntryId}
                    store={conversationStore}
                    usageValuesService={displayedUsageValuesService}
                />
                <ActionPromptOwner
                    action={action}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    questionsPanel={question ? <ActionAgentQuestionOwner bindingStore={bindingStore} /> : null}
                    settingsStore={settingsStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                />
                <ActionAgentApprovals bindingStore={bindingStore} />
            </Stack>
        </Stack>
    )
}

import { Stack } from '@mui/material'
import { useEffect, useMemo, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { agentAcknowledgementService } from '../../../services/agents/agent_acknowledgement_service'
import { cardPopupService, subscribeCardPopups } from '../../../services/card_popup_service'
import { useBoundRunId, useRunSelector } from '../../hooks/use_action_runs'
import {
    ActionConversationTranscript,
} from './action_conversation_transcript'
import {
    createAcknowledgementConversationSelector,
} from './action_conversation_chat_selectors'
import { resolveDisplayedConversation, type ActionConversationStore } from './action_conversation_store'
import { ConversationMetaInfo } from './conversation_meta_info'
import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'
import type { ActionUsageValuesService } from '../run/popup/action_usage_values_service'

interface ActionConversationChatProps {
    actionId: string
    bindingStore: ActionRunBindingStore
    context: ActionContext
    popupEntryId?: string
    store: ActionConversationStore
    usageValuesService?: ActionUsageValuesService
}

/** Conversation surface; owns selection, live-run, visibility, and acknowledgement subscriptions. */
export function ActionConversationChat(
    { actionId, bindingStore, context, popupEntryId, store, usageValuesService }: ActionConversationChatProps,
) {
    const selectAcknowledgementConversation = useMemo(() => createAcknowledgementConversationSelector(), [])
    const boundRunId = useBoundRunId(bindingStore)
    const liveConversation = useRunSelector(boundRunId, selectAcknowledgementConversation)
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const popupEntries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const conversation = resolveDisplayedConversation(liveConversation, selectedConversation)
    const scope = context.cardInternalId ?? null
    const popupVisible = context.kind === 'project' || popupEntries.at(-1)?.id === popupEntryId
    const visible = !!popupEntryId && popupVisible && !!conversation

    useEffect(() => {
        if (!popupEntryId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, scope, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId, scope, actionId, conversation, false,
        )
    }, [actionId, conversation, popupEntryId, scope, visible])

    return (
        <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
            <ActionConversationTranscript
                bindingStore={bindingStore}
                store={store}
            />
            <ConversationMetaInfo bindingStore={bindingStore} store={store} usageValuesService={usageValuesService} />
        </Stack>
    )
}

import { Stack } from '@mui/material'
import { memo, useCallback, useEffect, useLayoutEffect, useRef, useState, type UIEvent } from 'react'
import { dialogService } from '../../../services/dialog_service'
import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'
import { ActionConversationChatlogTracker } from './action_conversation_chatlog_tracker'
import { ActionConversationEvolvingGroups } from './action_conversation_evolving_groups'
import { ActionConversationHistory } from './action_conversation_history'
import { ActionConversationQueuedPrompts } from './action_conversation_queued_prompts'
import { ActionConversationReservedBlocks } from './action_conversation_reserved_blocks'
import type { ActionConversationStore } from './action_conversation_store'

const CHAT_END_TOLERANCE = 4
const MIN_CHAT_HEIGHT = 96

interface ActionConversationTranscriptProps {
    bindingStore: ActionRunBindingStore
    store: ActionConversationStore
    trackerFactory?: (
        bindingStore: ActionRunBindingStore,
        store: ActionConversationStore,
    ) => ActionConversationChatlogTracker
}

function createChatlogTracker(bindingStore: ActionRunBindingStore, store: ActionConversationStore) {
    return new ActionConversationChatlogTracker(bindingStore, store)
}

function viewportIsAtEnd(viewport: HTMLDivElement) {
    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE
}

/** Owns tracker lifecycle and renders subscribed transcript leaves. */
export const ActionConversationTranscript = memo(function ActionConversationTranscript(
    { bindingStore, store, trackerFactory = createChatlogTracker }: ActionConversationTranscriptProps,
) {
    const [tracker, setTracker] = useState<ActionConversationChatlogTracker | null>(null)
    const viewportRef = useRef<HTMLDivElement>(null)
    const viewportHeightRef = useRef<number | null>(null)
    const conversationIdentityRef = useRef<string | null>(null)
    const stuckToEndRef = useRef(true)

    const scrollToEnd = useCallback(() => {
        const viewport = viewportRef.current
        if (!viewport || !stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    }, [])

    const handleScroll = (event: UIEvent<HTMLDivElement>) => {
        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)
    }

    const handleViewportResize = useCallback(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const previousViewportHeight = viewportHeightRef.current
        const viewportHeight = viewport.clientHeight
        viewportHeightRef.current = viewportHeight
        if (previousViewportHeight === viewportHeight) return

        scrollToEnd()
    }, [scrollToEnd])

    useEffect(() => {
        const nextTracker = trackerFactory(bindingStore, store)
        setTracker(null)
        try {
            nextTracker.load()
            setTracker(nextTracker)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not load conversation chatlog' })
        }

        return () => nextTracker.unload()
    }, [bindingStore, store, trackerFactory])

    useEffect(() => {
        if (!tracker) return undefined

        const handleContentChange = () => {
            scrollToEnd()
            queueMicrotask(scrollToEnd)
        }
        const handleConversationChange = () => {
            const conversationIdentity = tracker.getConversationIdentity()
            if (conversationIdentityRef.current !== conversationIdentity) stuckToEndRef.current = true
            conversationIdentityRef.current = conversationIdentity
            handleContentChange()
        }
        conversationIdentityRef.current = tracker.getConversationIdentity()
        const unsubscribers = [
            tracker.subscribeStableGroups(handleContentChange),
            tracker.subscribeEvolvingGroups(handleContentChange),
            tracker.subscribeReservedBlockCount(handleContentChange),
            tracker.subscribeQueuedPrompts(handleContentChange),
            tracker.subscribeConversation(handleConversationChange),
        ]

        return () => {
            for (const unsubscribe of unsubscribers) unsubscribe()
        }
    }, [scrollToEnd, tracker])

    useLayoutEffect(scrollToEnd, [scrollToEnd, tracker])

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        viewportHeightRef.current = viewport.clientHeight
        const resizeObserver = new ResizeObserver(handleViewportResize)
        resizeObserver.observe(viewport)

        return resizeObserver.disconnect.bind(resizeObserver)
    }, [handleViewportResize])

    return (
        <Stack aria-label="Conversation chat" onScroll={handleScroll} ref={viewportRef} spacing={1}
            sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowX: 'hidden', overflowY: 'auto' }}>
            {tracker ? <ActionConversationHistory tracker={tracker} /> : null}
            {tracker ? <ActionConversationEvolvingGroups tracker={tracker} /> : null}
            {tracker ? <ActionConversationReservedBlocks tracker={tracker} /> : null}
            {tracker ? <ActionConversationQueuedPrompts tracker={tracker} /> : null}
        </Stack>
    )
})

